"Ukuran kertas & foto dihitung dalam milimeter asli, bukan diperkirakan — jadi hasil PDF/cetak presisi secara fisik.": "Paper & photo sizes are calculated in real millimeters, not estimated — so the PDF/print result is physically precise.",
