"PDF: gambar JPEG dikompres ulang, struktur dipadatkan. Mode agresif untuk PDF hasil scan.": "PDF: JPEG images are recompressed and the structure is compacted. Aggressive mode for scanned PDFs.",
"DOCX/XLSX/PPTX/ODT/EPUB: gambar di dalam dokumen dikompres ulang, ZIP ditulis ulang maksimal.": "DOCX/XLSX/PPTX/ODT/EPUB: images inside the document are recompressed and the ZIP is rewritten at maximum compression.",
"Hasil tidak pernah lebih besar dari aslinya — kalau tidak ada yang bisa dihemat, berkas asli dipertahankan.": "The result is never larger than the original — if nothing can be saved, the original file is kept.",
"DOC/XLS/PPT lama & berkas teks dibungkus ZIP (format biner lama tidak bisa dipadatkan aman di browser).": "Old DOC/XLS/PPT & text files are wrapped in a ZIP (the old binary formats can't be safely compacted in the browser).",
