"Hanya ubin peta (OpenStreetMap/OpenTopoMap/Esri), pencarian tempat/alamat (Nominatim), dan ketinggian (Open-Meteo) memakai internet — dan baru dipanggil bila Anda memakainya. Pilih “Peta dunia offline” untuk tanpa jaringan.": "Only map tiles (OpenStreetMap/OpenTopoMap/Esri), place/address search (Nominatim), and elevation (Open-Meteo) use the internet — and they're only called when you use them. Choose “Offline world map” for no network.",
