"Opus 24 kbps mono sudah jernih untuk suara bicara; 96–160 kbps stereo untuk musik.": "Opus 24 kbps mono is already clear for speech; 96–160 kbps stereo for music.",
"Dengan encoder cepat, proses jauh lebih singkat dari durasi audio. Tanpa itu, browser memakai mode real-time (durasi proses ≈ durasi audio).": "With the fast encoder, processing is much shorter than the audio duration. Without it, the browser uses real-time mode (processing time ≈ audio duration).",
"Format .opus didukung Chrome, Firefox, Edge, VLC & Android; Safari/iOS lama mungkin belum — gunakan WAV ringan atau Universal Converter.": "The .opus format is supported by Chrome, Firefox, Edge, VLC & Android; older Safari/iOS may not be — use lightweight WAV or Universal Converter.",
