"Audio didekode lewat Web Audio API lalu di-encode ke MP3 (LAME) langsung di browser — bukan real-time, jadi cepat (file 5 menit biasanya hitungan detik).": "Audio is decoded through the Web Audio API then encoded to MP3 (LAME) right in the browser — not real-time, so it's fast (a 5-minute file usually takes seconds).",
"MP3 diputar di hampir semua perangkat, mobil, dan platform. Bitrate lebih tinggi = lebih jernih tetapi file lebih besar.": "MP3 plays on almost every device, car, and platform. Higher bitrate = clearer but larger file.",
"File tidak pernah diunggah ke server mana pun.": "Files are never uploaded to any server.",
"Audio didekode lewat Web Audio API lalu ditulis ulang sebagai WAV PCM 16-bit — cara paling universal dan pasti bisa dibuka di mana saja.": "Audio is decoded through the Web Audio API then rewritten as 16-bit PCM WAV — the most universal way, guaranteed to open anywhere.",
