"Paragraf pembuka": "Opening paragraph",
"Menindaklanjuti kebijakan pimpinan terkait penyesuaian waktu kerja, dengan ini kami sampaikan hal-hal sebagai berikut:": "Following up on leadership's policy on adjusting working hours, we hereby convey the following:",
