"Jam kerja Senin–Kamis pukul 08.00–15.00 WIB\nJam kerja Jumat pukul 08.00–15.30 WIB\nIstirahat pukul 12.00–12.30 WIB\nKetentuan lain tetap mengikuti peraturan yang berlaku": "Working hours Monday–Thursday 8:00 AM–3:00 PM\nWorking hours Friday 8:00 AM–3:30 PM\nBreak 12:00–12:30 PM\nOther provisions follow the applicable regulations",
