"Berdasarkan hasil evaluasi, yang bersangkutan telah melakukan pelanggaran berupa {{pelanggaran}}.": "Based on the evaluation results, the person concerned has committed a violation in the form of {{pelanggaran}}.",
"Sehubungan dengan hal tersebut, kami menyampaikan:": "In connection with this, we convey the following:",
"Surat peringatan ini berlaku selama {{masa_berlaku}} sejak tanggal diterbitkan.\nKaryawan wajib memperbaiki kinerja dan kedisiplinan.\nApabila pelanggaran terulang, perusahaan akan memberikan sanksi yang lebih berat sesuai peraturan perusahaan.": "This warning letter is valid for {{masa_berlaku}} from the date of issue.\nThe employee must improve performance and discipline.\nIf the violation is repeated, the company will impose heavier sanctions under company regulations.",
"Demikian surat peringatan ini disampaikan untuk diperhatikan dan dilaksanakan sebagaimana mestinya.": "This warning letter is issued to be noted and carried out as appropriate.",
