"Pada hari ini, {{hari}}, tanggal {{tanggal}}, yang bertanda tangan di bawah ini:": "Today, {{hari}}, dated {{tanggal}}, the undersigned:",
"1. Nama": "1. Name",
"    Alamat": "    Address",
"selanjutnya disebut **PIHAK PERTAMA** (pemilik), dan": "hereinafter referred to as the **FIRST PARTY** (owner), and",
"2. Nama": "2. Name",
"selanjutnya disebut **PIHAK KEDUA** (penyewa). Kedua belah pihak sepakat mengadakan perjanjian sewa menyewa dengan ketentuan sebagai berikut:": "hereinafter referred to as the **SECOND PARTY** (tenant). Both parties agree to enter into a lease agreement under the following terms:",
"Pasal 1": "Article 1",
"Objek Sewa": "Leased Object",
"PIHAK PERTAMA menyewakan kepada PIHAK KEDUA {{objek}}.": "The FIRST PARTY leases to the SECOND PARTY {{objek}}.",
"Pasal 2": "Article 2",
"Jangka Waktu": "Term",
"Perjanjian ini berlaku selama {{lama}}, terhitung mulai tanggal {{mulai}}.": "This agreement is valid for {{lama}}, starting on {{mulai}}.",
"Pasal 3": "Article 3",
"Harga & Pembayaran": "Price & Payment",
"Harga sewa selama jangka waktu tersebut sebesar {{harga}}, yang dibayarkan oleh PIHAK KEDUA kepada PIHAK PERTAMA pada saat perjanjian ini ditandatangani.": "The rent for that term is {{harga}}, paid by the SECOND PARTY to the FIRST PARTY upon the signing of this agreement.",
"Pasal 4": "Article 4",
"Hak & Kewajiban": "Rights & Obligations",
"PIHAK KEDUA wajib menjaga dan merawat objek sewa dengan baik.\nPIHAK KEDUA dilarang menyewakan kembali objek sewa kepada pihak lain tanpa izin tertulis PIHAK PERTAMA.\nPIHAK KEDUA wajib mengembalikan objek sewa dalam keadaan baik pada saat jangka waktu berakhir.": "The SECOND PARTY must keep and maintain the leased object well.\nThe SECOND PARTY is prohibited from subletting the leased object to other parties without the FIRST PARTY's written permission.\nThe SECOND PARTY must return the leased object in good condition when the term ends.",
"Pasal 5": "Article 5",
"Penyelesaian Perselisihan": "Dispute Resolution",
"Apabila terjadi perselisihan, kedua belah pihak sepakat menyelesaikannya secara musyawarah. Jika tidak tercapai mufakat, perselisihan akan diselesaikan melalui Pengadilan Negeri {{kota_hukum}}.": "In the event of a dispute, both parties agree to settle it through deliberation. If no agreement is reached, the dispute will be settled through the {{kota_hukum}} District Court.",
"Demikian perjanjian ini dibuat rangkap dua bermaterai cukup, masing-masing mempunyai kekuatan hukum yang sama.": "This agreement is made in duplicate with sufficient stamp duty, each having the same legal force.",
